-- Audio Engine loader: procedural engine sound + rpm/speed HUD for registered cars
AUDIO_ENGINE = AUDIO_ENGINE or {}

local base = "audio_engine/"
local shared = { "sh_config.lua", "sh_presets.lua", "sh_drivetrain.lua", "sh_carlist.lua", "sh_perp.lua", "sh_police.lua" }
-- cl_baked.lua: generated by dev/baker (what the pre-generated sounds in sound/audio_engine/ are)
local client = { "cl_baked.lua", "cl_synth.lua", "cl_soundbank.lua", "cl_engine.lua", "cl_hud.lua", "cl_menu.lua", "cl_police.lua" }

if SERVER then
	for _, f in ipairs(shared) do AddCSLuaFile(base .. f) end
	for _, f in ipairs(client) do AddCSLuaFile(base .. f) end
end

for _, f in ipairs(shared) do include(base .. f) end

if SERVER then
	include(base .. "sv_perp_physics.lua")   -- generated: PERP's base-script physics per car
	include(base .. "sv_handling.lua")
	include(base .. "sv_engine.lua")
	include(base .. "sv_stability.lua")
	include(base .. "sv_cruise.lua")
	include(base .. "sv_police.lua")
else
	for _, f in ipairs(client) do include(base .. f) end
end

-- the debug tools (lua/audio_engine_debug/: script, gearing and rev editors, handling switches;
-- superadmins, audio_engine_debug). Loaded whenever the folder is there: to ship the addon
-- without them, delete the folder, nothing else
local dbg = "audio_engine_debug/"
if file.Exists(dbg .. "sh_debug.lua", "LUA") then
	if SERVER then
		for _, f in ipairs({ "sh_kv.lua", "sh_debug.lua", "cl_debug.lua", "cl_perf.lua" }) do AddCSLuaFile(dbg .. f) end
	end
	include(dbg .. "sh_kv.lua")
	include(dbg .. "sh_debug.lua")
	include(dbg .. (SERVER and "sv_debug.lua" or "cl_debug.lua"))
	-- the profiler (audio_engine_perf, audio_engine_perf_hud): measures nothing until it's turned on
	include(dbg .. (SERVER and "sv_perf.lua" or "cl_perf.lua"))
end
